117	// "#000000" + 0.24 -> "rgba(0, 0, 0, 0.24)". The token keeps the colour as hex
118	// so it reads like every other colour in the file; CSS needs it with an alpha.
119	function rgba(hex: string, opacity: number): string {
120	  const value = hex.replace('#', '');
121	  const channel = (at: number) => parseInt(value.slice(at, at + 2), 16);
122	  return `rgba(${channel(0)}, ${channel(2)}, ${channel(4)}, ${opacity})`;
123	}
