125	export function applyAppearance(appearance: Appearance): void {
126	  const semantic = (tokens as { semantic: Record<string, SemanticMode> }).semantic;
127	  const mode = semantic[appearance] ?? semantic.light;
128	  const root = document.documentElement;
129	  for (const [group, values] of Object.entries(mode)) {
130	    for (const [name, value] of Object.entries(values)) {
131	      if (typeof value === 'string') root.style.setProperty(`--${group}-${name}`, value);
132	    }
133	  }
134	  for (const [tier, shadow] of Object.entries(elevationTiers())) {
135	    const opacity = shadow.opacity[appearance] ?? shadow.opacity.light;
136	    root.style.setProperty(
137	      `--elevation-${kebab(tier)}`,
138	      `${shadow.offsetX}px ${shadow.offsetY}px ${shadow.blur}px ${shadow.spread}px ${rgba(shadow.color, opacity)}`,
139	    );

305	  border-radius: var(--swatch-radius);
