8	import tokens from '@resources/jusprin/ui/design-tokens.json';
9	
10	export type Appearance = 'light' | 'dark';
11	
12	type TokenGroup = Record<string, string>;
13	type SemanticMode = Record<string, TokenGroup>;
14	
15	export interface TypeRole {
16	  size: number;
17	  lineHeight: number;
18	  weight: number;
19	}
20	
21	interface ButtonRecipe {
22	  paddingX?: number;
23	  paddingY?: number;
24	}
25	
26	interface StaticTokens {
27	  dimension: { radius: Record<string, number> };
28	  typography: {
29	    ui: { family: string; cssFallback: string };
30	    code: TypeRole & { cssFamily: string };
31	    roles: Record<string, TypeRole>;
32	  };
33	  component: { button: Record<string, ButtonRecipe> };
34	}
