     1	// Guards the stylesheet's contract with resources/jusprin/ui/design-tokens.json:
     2	// colors, radii, and type metrics resolve through the custom properties that
     3	// tokens.ts emits, and spacing sits on the spacing scale. The file is read
     4	// from disk on purpose: importing the CSS under Vitest yields an empty string,
     5	// so a test written that way passes while asserting nothing.
     6	
     7	import { readFileSync } from 'node:fs';
     8	import { join } from 'node:path';
     9	import { describe, expect, it } from 'vitest';
    10	import { staticVariableNames } from './tokens';
    11	
    12	const SPACING_SCALE = [0, 4, 8, 12, 16, 20, 24, 32, 40, 48];
    13	
    14	const source = readFileSync(join(__dirname, 'styles.css'), 'utf8');
    15	
    16	// Blank out comments but keep every newline so reported line numbers match
    17	// the file.
    18	const css = source.replace(/\/\*[\s\S]*?\*\//g, (comment) => comment.replace(/[^\n]/g, ' '));
    19	const lines = css.split('\n');
    20	
    21	// Line numbers (1-based) covered by an @font-face block, where font metrics
    22	// are the declaration of the face itself rather than a use of it.
    23	function fontFaceLines(): Set<number> {
    24	  const covered = new Set<number>();
    25	  let depth = 0;
    26	  let inFontFace = false;
    27	  lines.forEach((line, index) => {
    28	    if (!inFontFace && /@font-face\b/.test(line)) inFontFace = true;
    29	    if (inFontFace) covered.add(index + 1);
    30	    for (const ch of line) {
    31	      if (ch === '{') depth += 1;
    32	      if (ch === '}') {
    33	        depth -= 1;
    34	        if (inFontFace && depth === 0) inFontFace = false;
    35	      }
    36	    }
    37	  });
    38	  return covered;
    39	}
    40	
    41	const exemptLines = fontFaceLines();
    42	
    43	function offending(pattern: RegExp, extra?: (line: string) => boolean): string[] {
    44	  const hits: string[] = [];
    45	  lines.forEach((line, index) => {
    46	    const number = index + 1;
    47	    if (exemptLines.has(number)) return;
    48	    if (pattern.test(line) && (!extra || extra(line))) hits.push(`${number}: ${line.trim()}`);
    49	  });
    50	  return hits;
    51	}
    52	
    53	describe('styles.css stays on the design tokens', () => {
    54	  it('was actually read', () => {
    55	    expect(source.trim().length).toBeGreaterThan(0);
    56	  });
    57	
    58	  it('carries no literal color', () => {
    59	    expect(offending(/#[0-9a-fA-F]{3,8}\b|\b(rgba?|hsla?)\(/)).toEqual([]);
    60	  });
    61	
    62	  it('carries no pixel border-radius', () => {
    63	    expect(offending(/border-radius\s*:[^;]*\d+px/)).toEqual([]);
    64	  });
    65	
    66	  // The patterns match after a `{` or `;` as well as at the start of a line,
    67	  // so a single-line rule cannot slip past them.
    68	  it('sets type only through the role variables', () => {
    69	    expect(offending(/(?:^|[{;])\s*(font-size|line-height|font-weight)\s*:/)).toEqual([]);
    70	    // A `font` shorthand with a literal size or line height would bypass the
    71	    // check above.
    72	    expect(offending(/(?:^|[{;])\s*font\s*:[^;]*\d+px/)).toEqual([]);
    73	  });
    74	
    75	  it('asks only for variables that tokens.ts emits', () => {
    76	    const emitted = new Set(staticVariableNames());
    77	    expect(emitted).toContain('--font-body-bold');
    78	    expect(emitted).toContain('--project-card-min-width');
    79	    expect(emitted).toContain('--printer-card-column-width');
    80	    const requested = [
    81	      ...css.matchAll(
    82	        /var\((--(?:font|button|project-card|printer-card|status-dot|swatch|glyph|elevation)-[\w-]+)\)/g,
    83	      ),
    84	    ].map((m) => m[1]);
    85	    expect(requested.length).toBeGreaterThan(0);
    86	    expect(requested.filter((name) => !emitted.has(name))).toEqual([]);
    87	  });
    88	
    89	  it('keeps padding, margin, and gap on the spacing scale', () => {
    90	    const offScale = offending(/^\s*(padding|margin|gap|row-gap|column-gap)(-[a-z]+)?\s*:/, (line) => {
    91	      const value = line.replace(/^[^:]*:/, '');
    92	      const pixels = [...value.matchAll(/(-?\d+(?:\.\d+)?)px/g)].map((m) => Math.abs(Number(m[1])));
    93	      return pixels.some((px) => !SPACING_SCALE.includes(px));
    94	    });
    95	    expect(offScale).toEqual([]);
    96	  });
    97	
    98	  // Section 2 of the handoff: as many columns as fit, each card between its
    99	  // own bounds. A fixed column count grows cards to fill a wide monitor, which
   100	  // is the mistake this rule exists to prevent.
   101	  it('sizes the gallery by the card bounds, not by a column count', () => {
   102	    const rule = css.match(/\.project-grid\s*\{[^}]*\}/);
   103	    expect(rule).not.toBeNull();
   104	    expect(rule![0]).toMatch(/auto-fill/);
   105	    expect(rule![0]).toMatch(/minmax\(\s*var\(--project-card-min-width\)\s*,\s*1fr\s*\)/);
   106	    // The ceiling belongs on the card, not on the track: auto-fill counts
   107	    // tracks by their maximum, so a 320px track cap fits two columns at 1280
   108	    // where three belong.
   109	    const card = css.match(/\.project-card\s*\{[^}]*\}/);
   110	    expect(card).not.toBeNull();
   111	    expect(card![0]).toMatch(/max-width:\s*var\(--project-card-max-width\)/);
   112	  });
   113	
   114	  // A 4:3 frame, never cropped: both a cropped model and an empty band above
   115	  // and below appeared in review.
   116	  it('keeps the thumbnail at the token aspect ratio and uncropped', () => {
   117	    const frame = css.match(/\.project-thumbnail\s*\{[^}]*\}/);
   118	    expect(frame).not.toBeNull();
   119	    expect(frame![0]).toMatch(/aspect-ratio:\s*var\(--project-card-thumbnail-aspect\)/);
   120	    const image = css.match(/\.project-thumbnail img\s*\{[^}]*\}/);
   121	    expect(image).not.toBeNull();
   122	    expect(image![0]).toMatch(/object-fit:\s*contain/);
   123	    // An in-flow image contributes its intrinsic height as the frame's minimum
   124	    // content height, which beats the ratio: every card holding a real .3mf
   125	    // thumbnail came out square in the app while cards without one, the only
   126	    // kind this suite can render, stayed 4:3. Out of flow, the ratio governs.
   127	    expect(image![0]).toMatch(/position:\s*absolute/);
   128	    expect(frame![0]).toMatch(/position:\s*relative/);
   129	  });
   130	
   131	  // A long name truncates rather than reflowing the grid.
   132	  it('truncates the project title on one line', () => {
   133	    const rule = css.match(/\.project-title\s*\{[^}]*\}/);
   134	    expect(rule).not.toBeNull();
   135	    expect(rule![0]).toMatch(/white-space:\s*nowrap/);
   136	    expect(rule![0]).toMatch(/text-overflow:\s*ellipsis/);
   137	  });
   138	
   139	  // The frames run the thumbnail straight into the footer. A rule separating
   140	  // them cuts the card in two, which is what it looked like before anyone
   141	  // compared it to the design.
   142	  it('does not rule a line between the thumbnail and the footer', () => {
   143	    const rule = css.match(/\.project-footer\s*\{[^}]*\}/);
   144	    expect(rule).not.toBeNull();
   145	    expect(rule![0]).not.toMatch(/border/);
   146	  });
   147	
   148	  // A platform scrollbar beside the rail's divider reads as a second, heavier
   149	  // line; the design has one divider there.
   150	  it('draws its own thin scrollbar in the gallery, invisible at rest', () => {
   151	    expect(css).toMatch(/\.gallery[^{]*\{[^}]*scrollbar-width:\s*thin/);
   152	    expect(css).toMatch(/\.gallery::-webkit-scrollbar-track[^{]*\{[^}]*background:\s*transparent/);
   153	    expect(css).toMatch(/\.gallery::-webkit-scrollbar-thumb[^{]*\{[^}]*background:\s*transparent/);
   154	    expect(css).toMatch(/\.gallery:hover::-webkit-scrollbar-thumb[^{]*\{[^}]*background:\s*var\(--border-subtle\)/);
   155	  });
   156	
   157	  // The tint is the state. An ordinary card sits on surface.raised and only a
   158	  // printing one is tinted; giving every card the tint leaves the printing
   159	  // card differing by its border alone, which is not what the frames show in
   160	  // either mode.
   161	  it('tints only the printing card', () => {
   162	    const card = css.match(/\.project-card\s*\{[^}]*\}/);
   163	    expect(card).not.toBeNull();
   164	    expect(card![0]).toMatch(/background:\s*var\(--surface-raised\)/);
   165	    const printing = css.match(/\.project-card\.printing\s*\{[^}]*\}/);
   166	    expect(printing).not.toBeNull();
   167	    expect(printing![0]).toMatch(/background:\s*var\(--surface-subtle\)/);
   168	    expect(printing![0]).toMatch(/border-color:\s*var\(--status-success\)/);
   169	  });
   170	
   171	  // One surface per card: a thumbnail frame with a ground of its own turns an
   172	  // image-less card into a light box stacked on a tinted strip.
   173	  it('gives the thumbnail frame no ground of its own', () => {
   174	    const rule = css.match(/\.project-thumbnail\s*\{[^}]*\}/);
   175	    expect(rule).not.toBeNull();
   176	    expect(rule![0]).not.toMatch(/background/);
   177	  });
   178	
   179	  // Both cards rest just above the surface, which is the Subtle tier. The
   180	  // design's audit replaced thirteen ad-hoc shadows with three tiers, so a
   181	  // literal here is the thing that must not come back.
   182	  it('lifts both cards with the subtle elevation token', () => {
   183	    for (const selector of [/\.project-card\s*\{[^}]*\}/, /\.printer-card\s*\{[^}]*\}/]) {
   184	      const rule = css.match(selector);
   185	      expect(rule).not.toBeNull();
   186	      expect(rule![0]).toMatch(/box-shadow:\s*var\(--elevation-subtle\)/);
   187	    }
   188	    // A shadow written out by hand would carry its own colour and escape the
   189	    // token file; the only box-shadow allowed to name a colour is none.
