75	//   --radius-<name>       e.g. --radius-container: 8px
76	//   --font-<role>         full `font` shorthand in the UI face, kebab-case
77	//   --font-code           the one monospace role, for code, keys, paths, IDs
78	//   --button-<recipe>-padding  "<y>px <x>px" from component.button; control
79	//                         padding follows the recipes, not the spacing scale
80	export function applySharedStaticTokens(): void {
81	  const { dimension, typography, component } = tokens as unknown as StaticTokens;
82	  const root = document.documentElement;
83	  for (const [name, value] of Object.entries(dimension.radius)) {
84	    root.style.setProperty(`--radius-${name}`, `${value}px`);
85	  }
86	  const uiFamily = `'${typography.ui.family}', ${typography.ui.cssFallback}`;
87	  for (const [name, role] of Object.entries(typography.roles)) {
88	    root.style.setProperty(`--font-${kebab(name)}`, fontShorthand(role, uiFamily));
89	  }
90	  root.style.setProperty('--font-code', fontShorthand(typography.code, typography.code.cssFamily));
91	  for (const [name, recipe] of Object.entries(component.button)) {
92	    if (recipe.paddingX === undefined || recipe.paddingY === undefined) continue;
93	    root.style.setProperty(`--button-${kebab(name)}-padding`, `${recipe.paddingY}px ${recipe.paddingX}px`);
94	  }

